<script lang="ts">
	import { BatteryCharging, Cable, Cpu, Database, Gauge, Info, Network, RadioTower, RefreshCw, Shield, SlidersHorizontal, Zap } from '@lucide/svelte';
	import { onMount } from 'svelte';
	import type { DeviceConfig } from '$lib/device-config';
	import { getEdgeConfig, getEvnModbusStatus, getEvnVpnControllers, getModem4GStatus, getNetworkActualStatus, getOpenvpnStatus, getRtsSystemStatus, getVpnChannelStatus, type Modem4GStatus, type RtsEdgeConfig } from '$lib/services/rts-api';

	let { config }: { config:DeviceConfig|null }=$props();
	let edge=$state<RtsEdgeConfig>({components:{},raw:null}),system=$state<any>({cpuUsage:null,ramUsage:null,diskUsage:null,firmware:null}),networkStatus=$state<Record<string,any>>({}),modem=$state<Modem4GStatus|null>(null),vpn=$state<any[]>([]),openvpn=$state<any>(null),evn=$state<any>(null),loading=$state(false),error=$state('');
	let rts=$derived(config?.rts as any),components=$derived(Object.entries(edge.components) as Array<[string,any]>);
	let tier=$derived(rts?.inverterSetup?.tiers?.[rts?.inverterSetup?.currentTier]??null);
	let serial=$derived(components.filter(([,item])=>item.factoryId==='Bridge.Modbus.Serial').map(([id,item])=>{const p=item.properties??{},name=rts?.serialPortTemplates?.find((v:any)=>v.key===id)?.displayName??id,parity=String(p.parity??'NONE').charAt(0),stop=p.stopbits==='TWO'?'2':p.stopbits==='ONE_POINT_FIVE'?'1.5':'1';return{name,value:`${p.baudRate??'—'}-${p.databits??'—'}${parity}${stop}`}}));
	let tcp=$derived(components.filter(([,item])=>item.factoryId==='Bridge.Modbus.Tcp').map(([id,item])=>{const p=item.properties??{},name=rts?.tcpBridgeTemplates?.find((v:any)=>v.key===id)?.displayName??id;return{name,value:`${p.ip??'—'}:${p.port??'—'}`}}));
	let inverters=$derived(components.filter(([,item])=>(rts?.inverterSetup?.inverterBrands??[]).some((brand:any)=>brand.factoryId===item.factoryId)));
	let totalPower=$derived(inverters.reduce((sum,[,item])=>sum+Number(item.properties?.maxActivePower??0)/1000,0));
	let meters=$derived(components.filter(([,item])=>(rts?.meterSetup?.meterBrands??[]).some((brand:any)=>brand.factoryId===item.factoryId)));
	let poi=$derived(meters.find(([,item])=>item.properties?.type==='GRID')?.[1]?.properties?.alias??'Not Set');
	let storage=$derived(components.filter(([,item])=>(rts?.storageSetup?.storageBrands??[]).some((brand:any)=>brand.factoryId===item.factoryId)));
	let loggers=$derived(components.filter(([,item])=>(rts?.smartLoggerSetup?.smartLoggerBrands??[]).some((brand:any)=>brand.factoryId===item.factoryId)));
	let fixed=$derived(components.find(([,item])=>item.factoryId==='Controller.PvInverter.FixPowerLimit')?.[1]?.properties??{}),reactive=$derived(components.find(([,item])=>item.factoryId==='Controller.PvInverter.LimitReactivePower')?.[1]?.properties??{});
	let evnMode=$derived(fixed.allowEvnControl===true),activePower=$derived(Number(evnMode&&evn?.pOutSetpointWatt!=null?evn.pOutSetpointWatt:fixed.powerLimit??0)/1000),activePercent=$derived(evnMode&&evn?.pOutSetpointPercent!=null?Number(evn.pOutSetpointPercent):totalPower>0?Math.round(activePower/totalPower*100):0),reactivePower=$derived(Number(evnMode&&evn?.qOutSetpointVar!=null?evn.qOutSetpointVar:reactive.reactivePowerLimit??0)/1000),reactivePercent=$derived(evnMode&&evn?.qOutSetpointPercent!=null?Number(evn.qOutSetpointPercent):Number(reactive.reactivePowerLimitPercent??0));

	onMount(()=>{void load();const timer=setInterval(()=>void pollRuntime(),5000);return()=>clearInterval(timer)});
	async function safe<T>(promise:Promise<T>,fallback:T){try{return await promise}catch{return fallback}}
	async function load(){loading=true;error='';try{const [edgeConfig,runtime,networkValue,modemValue,vpnControllers,openvpnValue,evnValue]=await Promise.all([getEdgeConfig(),getRtsSystemStatus(),getNetworkActualStatus(),getModem4GStatus(),getEvnVpnControllers(),safe(getOpenvpnStatus(),null),getEvnModbusStatus()]);edge=edgeConfig;system=runtime;networkStatus=networkValue;modem=modemValue;openvpn=openvpnValue;evn=evnValue;vpn=await Promise.all(vpnControllers.map(async(item:any)=>({...item,...await getVpnChannelStatus(String(item.id??item.pid??'EVNNPC0'))})))}catch(cause){error=cause instanceof Error?cause.message:'Unable to load RTS system status.'}finally{loading=false}}
	async function pollRuntime(){const [runtime,modemValue,evnValue]=await Promise.all([safe(getRtsSystemStatus(),system),safe(getModem4GStatus(),modem),safe(getEvnModbusStatus(),evn)]);system=runtime;modem=modemValue;evn=evnValue}
	function percent(value:unknown){return value===null||value===undefined?'N/A':`${Number(value).toFixed(1)}%`}
	function vpnUp(item:any){const state=String(item.phase1Status??(item.enabled?'UP':'DOWN')).toUpperCase();return state==='UP'||state==='CONNECTED'}
</script>

<section class="page"><div class="head"><div><h2>Health Monitor</h2><p>Live Hybrid platform, devices, connectivity and controller overview.</p></div><button class:loading class="refresh" disabled={loading} onclick={load}><RefreshCw size={17}/>Refresh</button></div>{#if error}<div class="request-error">{error}</div>{/if}
	<div class="grid">
		<article class="card"><header><span class="blue"><Info size={20}/></span><h3>System Information</h3></header><div class="body">{@render Row('Serial Number',rts?.systemInfo?.serialNumber??'N/A')}{@render Row('Firmware',system.firmware??config?.systemInfo?.firmwareVersion??'N/A')}{#if tier}{@render Row('Configuration Tier',`${tier.label} · ${tier.maxInverters} inverters / ${tier.maxTotalPowerKW} kWp`)}{/if}</div></article>
		<article class="card"><header><span class="blue"><Cpu size={20}/></span><h3>Task Manager</h3></header><div class="body">{@render Usage('CPU Usage',system.cpuUsage)}{@render Usage('RAM Usage',system.ramUsage)}{@render Usage('Disk Usage',system.diskUsage)}</div></article>
		<article class="card"><header><span class="green"><Cable size={20}/></span><h3>Serial & TCP</h3></header><div class="body">{#each serial as item}{@render Row(item.name,item.value)}{/each}{#each tcp as item}{@render Row(item.name,item.value)}{/each}{#if !serial.length&&!tcp.length}<p class="none">No ports configured.</p>{/if}</div></article>
		<article class="card"><header><span class="orange"><Zap size={20}/></span><h3>Inverters</h3></header><div class="body">{@render Row('Total Inverters',`${inverters.length} / ${tier?.maxInverters??'N/A'}`)}{@render Row('Total Power',`${totalPower.toFixed(2)} / ${tier?.maxTotalPowerKW??'N/A'} kWp`)}</div></article>
		<article class="card"><header><span class="pink"><Gauge size={20}/></span><h3>Meters</h3></header><div class="body">{@render Row('Total Meters',String(meters.length))}{@render Row('POI Meter',poi)}</div></article>
		{#if rts?.sidebarConfig?.ess?.visible!==false}<article class="card"><header><span class="teal"><BatteryCharging size={20}/></span><h3>Energy Storage</h3></header><div class="body">{@render Row('ESS Devices',String(storage.length))}</div></article>{/if}
		<article class="card"><header><span class="brown"><Database size={20}/></span><h3>Data Loggers</h3></header><div class="body">{@render Row('Data Loggers',String(loggers.length))}</div></article>
		<article class="card"><header><span class="cyan"><Network size={20}/></span><h3>Network</h3></header><div class="body">{@render Row('WAN 0',networkStatus.eth1?.ip??'—')}{@render Row('WAN 1',networkStatus.eth0?.ip??'—')}</div></article>
		<article class="card"><header><span class="pink"><RadioTower size={20}/></span><h3>4G / LTE</h3></header><div class="body">{@render Row('Status',modem?.status??'Not available',modem?.status==='CONNECTED'?'ok':'')}{@render Row('Signal',`${modem?.signalStrength??0}%`)}{@render Row('Carrier',modem?.operator??'—')}{@render Row('IP Address',modem?.ipAddress??'—')}</div></article>
		<article class="card"><header><span class="green"><Shield size={20}/></span><h3>VPN</h3></header><div class="body">{#each vpn as item}<div class="vpn"><div><strong>{item.alias||item.id||'IPsec'}</strong><span>{item.remotePublicIp??'—'}</span></div><em class:up={vpnUp(item)}>{vpnUp(item)?'UP':'DOWN'}</em><small>Phase 1: {String(item.phase1Status??'—')} · Phase 2: {String(item.phase2Status??'—')}</small></div>{/each}{#if String(openvpn?.status??'').toLowerCase()==='running'}{@render Row('OpenVPN',`Connected · ${openvpn.clientIp??'—'}`,'ok')}{/if}{#if !vpn.length&&String(openvpn?.status??'').toLowerCase()!=='running'}<p class="none">No VPN connection.</p>{/if}</div></article>
		<article class="card wide"><header><span class="orange"><SlidersHorizontal size={20}/></span><h3>Hybrid Controller</h3><em class="mode">{evnMode?'EVN Control':'Local Control'}</em></header><div class="hybrid"><div><span>Active Power (P)</span><strong><i class:on={evnMode?evn?.pOutEnabled===true:fixed.enabled===true}></i>{activePower.toFixed(2)} kW ({activePercent.toFixed(0)}%)</strong></div><div><span>Reactive Power (Q)</span><strong><i class:on={evnMode?evn?.qOutEnabled===true:reactive.enabled===true}></i>{reactivePower.toFixed(2)} kVAR ({reactivePercent.toFixed(0)}%)</strong></div></div></article>
	</div>
</section>

{#snippet Row(label:string,value:string,tone='')}<div class="row"><span>{label}</span><strong class:ok={tone==='ok'}>{value}</strong></div>{/snippet}
{#snippet Usage(label:string,value:number|null)}<div class="usage"><div><span>{label}</span><strong>{percent(value)}</strong></div><i><b style={`width:${Math.max(0,Math.min(100,value??0))}%`}></b></i></div>{/snippet}

<style>
	.page{animation:enter .18s ease-out}.head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:18px}.head h2{margin:0;color:#172b4d;font-size:24px;font-weight:500}.head p{margin:7px 0 0;color:#718096;font-size:16px}.refresh{display:flex;align-items:center;gap:7px;min-height:38px;padding:0 13px;border:1px solid #d8e0eb;border-radius:8px;color:#40516f;background:#fff;font:inherit;cursor:pointer}.refresh.loading :global(svg){animation:spin .8s linear infinite}.request-error{margin-bottom:13px;padding:10px 12px;border:1px solid #f2d1ce;border-radius:8px;color:#b42318;background:#fff3f2;font-size:14px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.card{min-width:0;overflow:hidden;border:1px solid #e1e7f0;border-radius:11px;background:#fff}.card header{display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:1px solid #edf0f4}.card header>span{display:grid;width:35px;height:35px;place-items:center;border-radius:9px}.card header>span.blue{color:#315bc1;background:#eaf0ff}.card header>span.green{color:#25804e;background:#eaf8ef}.card header>span.orange{color:#dc7a21;background:#fff2e6}.card header>span.pink{color:#c43f72;background:#ffeaf1}.card header>span.teal{color:#168693;background:#e5f7f8}.card header>span.brown{color:#795548;background:#f4ece9}.card header>span.cyan{color:#247eb2;background:#e8f5fb}.card h3{margin:0;color:#30415c;font-size:16px;font-weight:500}.body{min-height:126px;padding:8px 16px}.row{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;padding:11px 0;border-bottom:1px solid #f0f2f6}.row:last-child{border-bottom:0}.row span{color:#718096}.row strong{color:#31415c;font-weight:500;text-align:right}.row strong.ok{color:#28784e}.none{margin:14px 0;color:#8792a4}.usage{padding:9px 0}.usage div{display:flex;justify-content:space-between}.usage span{color:#718096}.usage strong{font-weight:500}.usage>i{display:block;height:5px;margin-top:7px;overflow:hidden;border-radius:3px;background:#edf1f6}.usage b{display:block;height:100%;border-radius:3px;background:#4771c8}.vpn{display:grid;grid-template-columns:1fr auto;gap:4px;padding:9px 0;border-bottom:1px solid #f0f2f6}.vpn div strong,.vpn div span{display:block}.vpn div strong{color:#31415c;font-weight:500}.vpn div span,.vpn small{color:#8792a4;font-size:13px}.vpn small{grid-column:1/-1}.vpn em{align-self:start;padding:4px 7px;border-radius:11px;color:#a53b32;background:#fff0ef;font-size:11px;font-style:normal}.vpn em.up{color:#28764d;background:#edf9f1}.wide{grid-column:span 2}.mode{margin-left:auto;padding:5px 9px;border-radius:13px;color:#276b96;background:#eaf5fb;font-size:12px;font-style:normal}.hybrid{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:#edf1f6}.hybrid>div{padding:17px;background:#fff}.hybrid span,.hybrid strong{display:block}.hybrid span{color:#718096}.hybrid strong{display:flex;align-items:center;gap:8px;margin-top:8px;color:#31415c;font-size:16px;font-weight:500}.hybrid i{width:8px;height:8px;border-radius:50%;background:#df4b43}.hybrid i.on{background:#2daa67}@keyframes spin{to{transform:rotate(360deg)}}@keyframes enter{from{opacity:0;transform:translateY(4px)}}@media(max-width:1100px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:720px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}.head{flex-direction:column}.hybrid{grid-template-columns:1fr}}
</style>
